"""Regenerate internal/pycompat/errno_windows.txt from a Windows Python.

Run from the repository root with the Windows interpreter (from WSL, for example
/mnt/c/Users/<user>/AppData/Local/Programs/Python/Python313/python.exe -I
internal/pycompat/testdata/gen_windows.py).

On Windows a Go syscall.Errno is a Win32 error code. Python maps such a code to an errno
with winerror_to_errno (PC/errmap.h) and the C runtime's open() reports
"[Errno <errno>] <CRT strerror>: '<path>'". Records:
  W lo-hi:errno ...  the mapping of codes 0..11999 whose errno is not EINVAL (22): a run of
                     codes that share errno ("lo-hi:e") or map to themselves ("lo-hi:=")
  E n text           the CRT's os.strerror(n), omitted when it is "Unknown error"
  K n Class          the OSError subclass for errno n, omitted for OSError itself
  X winerror text    str(OSError(errno, os.strerror(errno), "p")) and the class, for samples
"""
import os
import sys

if sys.platform != "win32":
    sys.exit("gen_windows.py: run it with a Windows Python")

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.dirname(HERE)
SAMPLES = [0, 1, 2, 3, 5, 6, 8, 18, 32, 80, 87, 109, 112, 145, 183, 206, 267, 1113, 1816, 9999, 10013, 10035,
           10054, 10060, 10061, 11999, 12000]


def mapped(w):
    return OSError(None, "m", None, w).errno


def runs():
    out, cur = [], None
    for w in range(12000):
        e = mapped(w)
        key = None if e == 22 else ("=" if e == w else str(e))
        if cur and key == cur[2] and w == cur[1] + 1:
            cur[1] = w
            continue
        if cur:
            out.append("%d-%d:%s" % tuple(cur))
        cur = [w, w, key] if key else None
    if cur:
        out.append("%d-%d:%s" % tuple(cur))
    return out


def pack(kind, entries, width=200):
    lines, cur = [], kind
    for e in entries:
        if len(cur) + 1 + len(e) > width and cur != kind:
            lines.append(cur)
            cur = kind
        cur += " " + e
    if cur != kind:
        lines.append(cur)
    return lines


def main():
    lines = ["# generated by internal/pycompat/testdata/gen_windows.py: Python %s on %s; do not edit"
             % (sys.version.split()[0], sys.platform)]
    lines += pack("W", runs())
    lines += ["E %d %s" % (n, os.strerror(n)) for n in range(256) if os.strerror(n) != "Unknown error"]
    lines += ["K %d %s" % (n, type(OSError(n, "x")).__name__) for n in range(12000)
              if type(OSError(n, "x")) is not OSError]
    for w in SAMPLES:
        e = OSError(mapped(w), os.strerror(mapped(w)), "p")
        lines.append("X %d %s %s" % (w, type(e).__name__, str(e)))
    with open(os.path.join(PKG, "errno_windows.txt"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write("\n".join(lines) + "\n")
    print("errno_windows.txt written", file=sys.stderr)


if __name__ == "__main__":
    main()
